BEGIN TRANSACTION;
CREATE TABLE access_grants(kind TEXT NOT NULL,uid TEXT NOT NULL,target TEXT NOT NULL,position INTEGER NOT NULL,PRIMARY KEY(kind,uid,target),FOREIGN KEY(kind,uid) REFERENCES grant_subjects(kind,uid) ON DELETE CASCADE);
CREATE TABLE access_sections(name TEXT PRIMARY KEY);
CREATE TABLE catalog_projects(key TEXT PRIMARY KEY,position INTEGER NOT NULL,id TEXT,title TEXT,fields INTEGER NOT NULL,extensions TEXT NOT NULL);
CREATE TABLE catalog_sections(name TEXT PRIMARY KEY);
CREATE TABLE catalog_tasks(key TEXT PRIMARY KEY,position INTEGER NOT NULL,id TEXT,project_id TEXT,title TEXT,status TEXT,read_only INTEGER CHECK(read_only IN (0,1)),fields INTEGER NOT NULL,extensions TEXT NOT NULL);
CREATE TABLE grant_subjects(kind TEXT NOT NULL CHECK(kind IN ('thread_grants','project_grants','thread_denies')),uid TEXT NOT NULL,PRIMARY KEY(kind,uid));
CREATE TABLE mailbox(id INTEGER PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE member_bindings(username TEXT PRIMARY KEY,uid INTEGER NOT NULL);
CREATE TABLE member_policies(uid TEXT PRIMARY KEY,requires_approval INTEGER NOT NULL CHECK(requires_approval IN (0,1)));
CREATE TABLE preserved_history(id INTEGER PRIMARY KEY,text TEXT);
CREATE TABLE request_attachments(request_key TEXT NOT NULL,position INTEGER NOT NULL,id TEXT NOT NULL,name TEXT NOT NULL,size INTEGER NOT NULL,sha256 TEXT NOT NULL,extensions TEXT NOT NULL,PRIMARY KEY(request_key,position),FOREIGN KEY(request_key) REFERENCES workspace_requests(key) ON DELETE CASCADE);
CREATE TABLE request_events(request_key TEXT NOT NULL,position INTEGER NOT NULL,value TEXT NOT NULL,PRIMARY KEY(request_key,position),FOREIGN KEY(request_key) REFERENCES workspace_requests(key) ON DELETE CASCADE);
CREATE TABLE request_sections(name TEXT PRIMARY KEY);
CREATE TABLE workspace_requests(key TEXT PRIMARY KEY,position INTEGER NOT NULL,id INTEGER,source TEXT,channel TEXT,sender INTEGER,message INTEGER,thread TEXT,text TEXT,snapshot TEXT,created INTEGER,expires INTEGER,status TEXT,nonce TEXT,card TEXT,reply TEXT,approved_by INTEGER,decision_at INTEGER,approval_source TEXT,lease TEXT,lease_until INTEGER,delivered_at INTEGER,result_revision INTEGER,result_digest TEXT,result_status TEXT,result_updated INTEGER,fields INTEGER NOT NULL,extensions TEXT NOT NULL);
CREATE TABLE workspace_uploads(key TEXT PRIMARY KEY,position INTEGER NOT NULL,id TEXT,owner INTEGER,thread TEXT,name TEXT,size INTEGER,sha256 TEXT,created INTEGER,expires INTEGER,status TEXT,request_id TEXT,used_by INTEGER,fields INTEGER NOT NULL,extensions TEXT NOT NULL);
CREATE INDEX catalog_tasks_project ON catalog_tasks(project_id);
CREATE INDEX requests_status ON workspace_requests(status,created);
CREATE INDEX requests_thread ON workspace_requests(thread,created);
CREATE INDEX uploads_owner_nonce ON workspace_uploads(owner,request_id);
COMMIT;
PRAGMA user_version=3;
